<?php
declare(strict_types=1);
use Vendi\Database\Connection;use Vendi\Http\ApiGuard;
require dirname(__DIR__,3).'/vendor/autoload.php';session_start();header('Content-Type: application/json; charset=utf-8');
try{$u=ApiGuard::session();$db=Connection::get();$b=(int)$u['business_id'];$id=(int)($_GET['id']??0);$q=$db->prepare("SELECT c.*,pl.name price_level_name FROM customers c LEFT JOIN product_price_levels pl ON pl.id=c.price_level_id WHERE c.business_id=? AND c.id=?");$q->execute([$b,$id]);$c=$q->fetch();if(!$c)throw new RuntimeException('Cliente no encontrado.');$d=$db->prepare("SELECT id,original_name,mime_type,file_size,created_at FROM customer_documents WHERE business_id=? AND customer_id=? ORDER BY created_at DESC");$d->execute([$b,$id]);$h=$db->prepare("SELECT id,completed_at,total,status FROM sales WHERE business_id=? AND customer_id=? ORDER BY id DESC LIMIT 100");$h->execute([$b,$id]);$sum=$db->prepare("SELECT COUNT(*) tickets,COALESCE(SUM(total),0) purchased,MAX(completed_at) last_purchase FROM sales WHERE business_id=? AND customer_id=? AND status='completed'");$sum->execute([$b,$id]);echo json_encode(['ok'=>true,'customer'=>$c,'documents'=>$d->fetchAll(),'sales'=>$h->fetchAll(),'summary'=>$sum->fetch()],JSON_UNESCAPED_UNICODE);}catch(Throwable$e){http_response_code(400);echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}
